export { ChartCard, ChartTray, Swatch } from "./ChartCard";
export type { ChartCardProps, ChartSize, ChartTable, LegendItem } from "./ChartCard";
export { ChartTooltip } from "./ChartTooltip";
export type { ChartTooltipProps, TooltipRow } from "./ChartTooltip";
export { LineChart, AreaChart } from "./LineChart";
export type { LineChartProps, ChartSeries, Datum } from "./LineChart";
export { BarChart } from "./BarChart";
export type { BarChartProps } from "./BarChart";
export { DonutChart } from "./DonutChart";
export type { DonutChartProps, DonutDatum } from "./DonutChart";
export { RadarChart } from "./RadarChart";
export type { RadarChartProps } from "./RadarChart";
export { ScatterChart } from "./ScatterChart";
export type { ScatterChartProps, ScatterPoint, ScatterSeries } from "./ScatterChart";
export { RadialBarChart } from "./RadialBarChart";
export type { RadialBarChartProps, RadialBarDatum } from "./RadialBarChart";
export { Sparkline } from "./Sparkline";
export type { SparklineProps } from "./Sparkline";

// Pure geometry for the charts: scales, nice ticks, path builders and the series tones.
// No React here, so every chart draws from the same arithmetic.

export const EASE_OUT = [0.32, 0.72, 0, 1] as const;

export type Pt = readonly [number, number];

// Series are told apart by luminance and line style, never hue. Tone 0 is the popout series,
// the lightest thing in the plot; the rest step down and change dash so they read in greyscale,
// in print and for colour-blind readers alike.
export interface SeriesTone {
  stroke: string;
  fill: string;
  dash?: string;
  /** Opacity at the top of an area fill. */
  area: number;
}

export const TONES: SeriesTone[] = [
  { stroke: "#ededed", fill: "#e6e6e6", area: 0.16 },
  { stroke: "rgba(255,255,255,0.5)", fill: "rgba(255,255,255,0.46)", dash: "5 4", area: 0.06 },
  { stroke: "rgba(255,255,255,0.3)", fill: "rgba(255,255,255,0.27)", dash: "1.5 4", area: 0.045 },
  { stroke: "rgba(255,255,255,0.2)", fill: "rgba(255,255,255,0.16)", dash: "7 3 1.5 3", area: 0.035 },
];

export const tone = (i: number) => TONES[((i % TONES.length) + TONES.length) % TONES.length];

// Parts of a whole (donut, radial rings) need more steps than lines do.
export const SLICE_FILLS = [
  "",
  "rgba(255,255,255,0.58)",
  "rgba(255,255,255,0.4)",
  "rgba(255,255,255,0.27)",
  "rgba(255,255,255,0.18)",
  "rgba(255,255,255,0.11)",
];

/** A slice fill: the popout gradient for the first, then stepped greys. */
export const sliceFill = (i: number, popId: string) =>
  i === 0 ? `url(#${popId})` : SLICE_FILLS[Math.min(i, SLICE_FILLS.length - 1)];

export const r2 = (n: number) => Math.round(n * 100) / 100;
export const clamp = (v: number, lo: number, hi: number) => Math.min(Math.max(v, lo), hi);
export const num = (v: unknown) => (typeof v === "number" && Number.isFinite(v) ? v : Number(v) || 0);

/** Maps a domain onto a range, linearly. */
export const linear = (d0: number, d1: number, r0: number, r1: number) => (v: number) =>
  r0 + ((v - d0) / (d1 - d0 || 1)) * (r1 - r0);

function niceStep(span: number, count: number) {
  const raw = span / Math.max(1, count);
  const p = 10 ** Math.floor(Math.log10(raw || 1));
  const e = raw / p;
  return (e >= 7.5 ? 10 : e >= 3.5 ? 5 : e >= 1.5 ? 2 : 1) * p;
}

/** Rounds a domain out to tidy numbers and lists the ticks inside it. */
export function niceDomain(lo: number, hi: number, count = 4) {
  if (lo === hi) hi = lo + 1;
  const step = niceStep(hi - lo, count);
  const min = Math.floor(lo / step) * step;
  const max = Math.ceil(hi / step) * step;
  const ticks: number[] = [];
  for (let v = min; v <= max + step / 2; v += step) ticks.push(Math.round(v / step) * step);
  return { min, max, ticks };
}

/** 1.2k, 3.4M — short numbers for axes. */
export function compact(n: number) {
  const a = Math.abs(n);
  const trim = (v: number) => v.toFixed(1).replace(/\.0$/, "");
  if (a >= 1e9) return `${trim(n / 1e9)}B`;
  if (a >= 1e6) return `${trim(n / 1e6)}M`;
  if (a >= 1e3) return `${trim(n / 1e3)}k`;
  return Number.isInteger(n) ? String(n) : trim(n);
}

export const linePath = (pts: Pt[]) =>
  pts.map((p, i) => `${i ? "L" : "M"}${r2(p[0])},${r2(p[1])}`).join("");

/** A monotone cubic through the points: smooth, but never overshoots the data. */
export function smoothPath(pts: Pt[]) {
  const n = pts.length;
  if (n < 3) return linePath(pts);
  const m: number[] = [];
  for (let i = 0; i < n - 1; i++) m.push((pts[i + 1][1] - pts[i][1]) / (pts[i + 1][0] - pts[i][0] || 1));
  const t: number[] = [m[0]];
  for (let i = 1; i < n - 1; i++) t.push(m[i - 1] * m[i] <= 0 ? 0 : (m[i - 1] + m[i]) / 2);
  t.push(m[n - 2]);
  for (let i = 0; i < n - 1; i++) {
    if (m[i] === 0) {
      t[i] = 0;
      t[i + 1] = 0;
      continue;
    }
    const a = t[i] / m[i];
    const b = t[i + 1] / m[i];
    const s = a * a + b * b;
    if (s > 9) {
      const tau = 3 / Math.sqrt(s);
      t[i] = tau * a * m[i];
      t[i + 1] = tau * b * m[i];
    }
  }
  let d = `M${r2(pts[0][0])},${r2(pts[0][1])}`;
  for (let i = 0; i < n - 1; i++) {
    const [x0, y0] = pts[i];
    const [x1, y1] = pts[i + 1];
    const h = (x1 - x0) / 3;
    d += `C${r2(x0 + h)},${r2(y0 + t[i] * h)},${r2(x1 - h)},${r2(y1 - t[i + 1] * h)},${r2(x1)},${r2(y1)}`;
  }
  return d;
}

export function areaPath(pts: Pt[], baseY: number, smooth: boolean) {
  if (!pts.length) return "";
  const top = smooth ? smoothPath(pts) : linePath(pts);
  return `${top}L${r2(pts[pts.length - 1][0])},${r2(baseY)}L${r2(pts[0][0])},${r2(baseY)}Z`;
}

/** A point on a circle; 0° is twelve o'clock, angles run clockwise. */
export function polar(cx: number, cy: number, r: number, deg: number): Pt {
  const a = (deg * Math.PI) / 180;
  return [r2(cx + r * Math.sin(a)), r2(cy - r * Math.cos(a))];
}

/** An open arc, for stroking. */
export function arcPath(cx: number, cy: number, r: number, a0: number, a1: number) {
  const span = Math.min(a1 - a0, 359.99);
  const [x0, y0] = polar(cx, cy, r, a0);
  const [x1, y1] = polar(cx, cy, r, a0 + span);
  return `M${x0},${y0}A${r},${r} 0 ${span > 180 ? 1 : 0} 1 ${x1},${y1}`;
}

/** A filled ring segment between two radii; a wedge when the inner radius is 0. */
export function ringSegment(cx: number, cy: number, r0: number, r1: number, a0: number, a1: number) {
  const span = Math.min(a1 - a0, 359.99);
  const large = span > 180 ? 1 : 0;
  const [ox0, oy0] = polar(cx, cy, r1, a0);
  const [ox1, oy1] = polar(cx, cy, r1, a0 + span);
  if (r0 <= 0) return `M${cx},${cy}L${ox0},${oy0}A${r1},${r1} 0 ${large} 1 ${ox1},${oy1}Z`;
  const [ix0, iy0] = polar(cx, cy, r0, a0);
  const [ix1, iy1] = polar(cx, cy, r0, a0 + span);
  return `M${ox0},${oy0}A${r1},${r1} 0 ${large} 1 ${ox1},${oy1}L${ix1},${iy1}A${r0},${r0} 0 ${large} 0 ${ix0},${iy0}Z`;
}

/** A bar whose data end (the side away from the baseline) is rounded. */
export function barPath(x: number, y: number, w: number, h: number, radius: number, end: "top" | "bottom" | "right" | "left" | "none") {
  if (w <= 0 || h <= 0) return "";
  const r = Math.max(0, Math.min(radius, w / 2, h / 2));
  const [X, Y, W, H, R] = [x, y, w, h, r].map(r2);
  const arc = (tx: number, ty: number) => `A${R},${R} 0 0 1 ${r2(tx)},${r2(ty)}`;
  switch (end) {
    case "top":
      return `M${X},${Y + H}L${X},${Y + R}${arc(X + R, Y)}L${X + W - R},${Y}${arc(X + W, Y + R)}L${X + W},${Y + H}Z`;
    case "bottom":
      return `M${X},${Y}L${X + W},${Y}L${X + W},${Y + H - R}${arc(X + W - R, Y + H)}L${X + R},${Y + H}${arc(X, Y + H - R)}Z`;
    case "right":
      return `M${X},${Y}L${X + W - R},${Y}${arc(X + W, Y + R)}L${X + W},${Y + H - R}${arc(X + W - R, Y + H)}L${X},${Y + H}Z`;
    case "left":
      return `M${X + W},${Y + H}L${X + R},${Y + H}${arc(X, Y + H - R)}L${X},${Y + R}${arc(X + R, Y)}L${X + W},${Y}Z`;
    default:
      return `M${X},${Y}H${X + W}V${Y + H}H${X}Z`;
  }
}

"use client";

import { useCallback, useEffect, useRef, useState, type KeyboardEvent } from "react";
import { animate } from "framer-motion";
import { EASE_OUT } from "./scale";

const reducedMotion = () =>
  typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/**
 * Tweens a list of numbers toward `target`. On mount it rises from zero (when `fromZero`), and on
 * every change it glides from where it is. Under reduced motion it jumps straight to the target.
 */
export function useTween(target: number[], fromZero = true, duration = 0.8) {
  const [shown, setShown] = useState<number[]>(() => (fromZero ? target.map(() => 0) : target));
  const shownRef = useRef(shown);
  const key = target.join(",");

  useEffect(() => {
    const to = target;
    const from = shownRef.current;
    const set = (v: number[]) => {
      shownRef.current = v;
      setShown(v);
    };
    if (reducedMotion()) {
      set(to);
      return;
    }
    const controls = animate(0, 1, {
      duration,
      ease: EASE_OUT,
      onUpdate: (t) => set(to.map((v, i) => (from[i] ?? 0) + (v - (from[i] ?? 0)) * t)),
    });
    return () => controls.stop();
    // `key` stands in for the array's contents.
  }, [key, duration]);

  return target.map((_, i) => shown[i] ?? 0);
}

/** The content width of an element, kept current with a ResizeObserver. */
export function useWidth<T extends HTMLElement>() {
  const [width, setWidth] = useState(0);
  const observer = useRef<ResizeObserver | null>(null);
  const ref = useCallback((node: T | null) => {
    observer.current?.disconnect();
    if (!node) return;
    setWidth(node.clientWidth);
    observer.current = new ResizeObserver(([entry]) => setWidth(Math.round(entry.contentRect.width)));
    observer.current.observe(node);
  }, []);
  useEffect(() => () => observer.current?.disconnect(), []);
  return [ref, width] as const;
}

/** Arrow-key movement through `count` items, for focusable plots. */
export function useActiveIndex(count: number) {
  const [active, setActive] = useState<number | null>(null);
  const onKeyDown = (e: KeyboardEvent) => {
    const step = e.key === "ArrowRight" || e.key === "ArrowDown" ? 1 : e.key === "ArrowLeft" || e.key === "ArrowUp" ? -1 : 0;
    if (e.key === "Home" || e.key === "End") {
      e.preventDefault();
      setActive(e.key === "Home" ? 0 : count - 1);
    } else if (step) {
      e.preventDefault();
      setActive((a) => (a == null ? (step > 0 ? 0 : count - 1) : Math.min(Math.max(a + step, 0), count - 1)));
    } else if (e.key === "Escape") setActive(null);
  };
  const focusProps = {
    tabIndex: 0,
    onKeyDown,
    onFocus: () => setActive((a) => a ?? count - 1),
    onBlur: () => setActive(null),
  };
  return { active, setActive, focusProps };
}

"use client";

// Recessive axes shared by the cartesian charts: grid lines cut faintly into the tray, tick labels
// in tertiary ink at 10.5px. The zero line is one step firmer, so the baseline reads.

const LABEL = "rgb(115 115 115)";
const FONT = { fontSize: 10.5, fontFeatureSettings: "'tnum'" } as const;

export function YGrid({
  ticks,
  y,
  x0,
  x1,
  format,
  grid = true,
}: {
  ticks: number[];
  y: (v: number) => number;
  x0: number;
  x1: number;
  format: (v: number) => string;
  grid?: boolean;
}) {
  return (
    <g aria-hidden>
      {ticks.map((t) => (
        <g key={t}>
          {(grid || t === 0) && (
            <line
              x1={x0}
              x2={x1}
              y1={Math.round(y(t)) + 0.5}
              y2={Math.round(y(t)) + 0.5}
              stroke={t === 0 ? "rgba(255,255,255,0.09)" : "rgba(255,255,255,0.045)"}
            />
          )}
          <text x={x0 - 8} y={y(t)} textAnchor="end" dominantBaseline="middle" fill={LABEL} style={FONT}>
            {format(t)}
          </text>
        </g>
      ))}
    </g>
  );
}

/** Category labels along the bottom, thinned so they never collide. */
export function XLabels({
  labels,
  x,
  y,
  width,
  minGap = 52,
  edgeAlign = true,
}: {
  labels: string[];
  x: (i: number) => number;
  y: number;
  width: number;
  minGap?: number;
  edgeAlign?: boolean;
}) {
  const n = labels.length;
  const every = Math.max(1, Math.ceil(n / Math.max(1, Math.floor(width / minGap))));
  return (
    <g aria-hidden>
      {labels.map((l, i) => {
        if (i % every !== 0) return null;
        const anchor = edgeAlign && n > 1 && i === 0 ? "start" : edgeAlign && n > 1 && i === n - 1 ? "end" : "middle";
        return (
          <text key={i} x={x(i)} y={y} textAnchor={anchor} fill={LABEL} style={FONT}>
            {l}
          </text>
        );
      })}
    </g>
  );
}

/** Rough width of a tick label, to size the left gutter. */
export const labelWidth = (labels: string[]) => Math.max(14, ...labels.map((l) => l.length * 6.2)) + 12;

"use client";

import { forwardRef, type HTMLAttributes, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { tone } from "./scale";

// The shell every chart sits in: a raised card with the prismatic edge, a header (title, a
// headline value and a delta chip), the plot cut into the card as a recessed tray, and a legend.
// A visually hidden table carries the data for screen readers, the way Gauge carries a <meter>.

export type ChartSize = "sm" | "md" | "lg" | "fluid";

export interface LegendItem {
  label: ReactNode;
  tone: number;
  /** The swatch draws the series' real mark. Default "line". */
  mark?: "line" | "bar" | "dot";
  /** A custom fill for "bar" swatches (donut slices, rings). */
  fill?: string;
}

export interface ChartTable {
  columns: string[];
  rows: (string | number)[][];
}

export interface ChartCardProps extends Omit<HTMLAttributes<HTMLDivElement>, "title"> {
  /** Card title, and the chart's accessible name. */
  label?: ReactNode;
  /** A line under the title. */
  description?: ReactNode;
  /** The headline number. */
  value?: ReactNode;
  /** Small text beside the headline ("vs last month"). */
  valueCaption?: ReactNode;
  /** Change since the last period; shows as a chip with a status dot and a signed number. */
  delta?: number;
  /** Formats the delta. Default: signed percent with one decimal. */
  formatDelta?: (delta: number) => string;
  /** Whether a rise is good. Set false for latency, churn, cost. Default true. */
  higherIsBetter?: boolean;
  /** Replaces the delta chip in the header's right slot. */
  action?: ReactNode;
  legend?: LegendItem[];
  /** Card width: 320, 440 or 600px, or "fluid" to fill the parent. Default "md". */
  size?: ChartSize;
  /** The data, as a table for screen readers. */
  table?: ChartTable;
}

const WIDTH = { sm: 320, md: 440, lg: 600 };
const SUCCESS = "rgb(126 190 152)";
const DANGER = "rgb(229 115 115)";
const POPOUT_CSS = "linear-gradient(180deg,#f5f5f5 0%,#d9d9d9 100%)";

const defaultDelta = (d: number) => `${d > 0 ? "+" : d < 0 ? "−" : ""}${Math.abs(d).toFixed(1)}%`;

export const ChartCard = forwardRef<HTMLDivElement, ChartCardProps & { labelId?: string }>(function ChartCard(
  {
    label,
    description,
    value,
    valueCaption,
    delta,
    formatDelta = defaultDelta,
    higherIsBetter = true,
    action,
    legend,
    size = "md",
    table,
    labelId,
    className,
    style,
    children,
    ...rest
  },
  ref
) {
  const trend = delta == null || delta === 0 ? "flat" : (delta > 0) === higherIsBetter ? "good" : "bad";

  return (
    <div
      {...rest}
      ref={ref}
      data-trend={delta == null ? undefined : trend}
      className={cn(
        "relative flex min-w-0 flex-col overflow-hidden rounded-3xl border border-white/[0.08] p-5",
        "bg-[linear-gradient(180deg,#1b1b1d_0%,#151516_100%)]",
        "shadow-[inset_0_1.5px_0_0_rgba(255,255,255,0.08),inset_0_-1px_0_0_rgba(0,0,0,0.5),0_14px_30px_-10px_rgba(0,0,0,0.5),0_1px_4px_-1px_rgba(0,0,0,0.35)]",
        size === "fluid" && "w-full",
        className
      )}
      style={size === "fluid" ? style : { width: WIDTH[size], maxWidth: "100%", ...style }}
    >
      {/* Prismatic top edge. */}
      <span
        aria-hidden
        className="pointer-events-none absolute inset-x-0 top-0 h-[1.5px] bg-[linear-gradient(90deg,transparent_0%,rgba(255,255,255,0.18)_25%,rgba(255,255,255,0.32)_50%,rgba(255,255,255,0.18)_75%,transparent_100%)]"
      />

      {(label || description || action || delta != null) && (
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            {label && (
              <div id={labelId} className="truncate text-sm font-medium tracking-tight text-neutral-100">
                {label}
              </div>
            )}
            {description && <div className="mt-0.5 truncate text-xs text-neutral-500">{description}</div>}
          </div>
          {action ??
            (delta != null && (
              <span className="flex h-5 shrink-0 items-center gap-1.5 rounded-md border border-white/[0.06] bg-[#070707] px-1.5 text-[11px] font-medium tabular-nums text-neutral-400 shadow-[inset_0_1.5px_3px_rgba(0,0,0,0.85),0_1px_0_rgba(255,255,255,0.05)]">
                <span
                  aria-hidden
                  className="size-[5px] rounded-full bg-neutral-500"
                  style={trend === "flat" ? undefined : { backgroundColor: trend === "good" ? SUCCESS : DANGER }}
                />
                {formatDelta(delta)}
              </span>
            ))}
        </div>
      )}

      {value != null && (
        <div className="mt-3 flex items-baseline gap-2">
          <span className="text-[28px] font-semibold leading-none tracking-[-0.04em] text-neutral-100 tabular-nums">{value}</span>
          {valueCaption && <span className="truncate text-xs text-neutral-500">{valueCaption}</span>}
        </div>
      )}

      {children}

      {legend && legend.length > 0 && (
        <div className="mt-3.5 flex flex-wrap gap-x-4 gap-y-1.5" aria-hidden>
          {legend.map((item, i) => (
            <span key={i} className="flex items-center gap-1.5 text-xs text-neutral-400">
              <Swatch tone={item.tone} mark={item.mark} fill={item.fill} />
              {item.label}
            </span>
          ))}
        </div>
      )}

      {table && (
        <table className="sr-only">
          {typeof label === "string" && <caption>{label}</caption>}
          <thead>
            <tr>
              {table.columns.map((c) => (
                <th key={c} scope="col">
                  {c}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {table.rows.map((row, i) => (
              <tr key={i}>
                {row.map((cell, j) => (j === 0 ? <th key={j} scope="row">{cell}</th> : <td key={j}>{cell}</td>))}
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
});

/** The plot area: a recessed tray cut into the card, one tier darker. */
export const ChartTray = forwardRef<HTMLDivElement, HTMLAttributes<HTMLDivElement>>(function ChartTray(
  { className, ...rest },
  ref
) {
  return (
    <div
      {...rest}
      ref={ref}
      className={cn(
        "relative mt-4 rounded-2xl border border-white/[0.05] bg-[#0c0c0d] shadow-[inset_0_2px_6px_rgba(0,0,0,0.8),0_1px_0_rgba(255,255,255,0.05)]",
        "outline-none focus-visible:outline focus-visible:outline-1 focus-visible:outline-offset-2 focus-visible:outline-white/40",
        className
      )}
    />
  );
});

/** A legend swatch drawn as the series' own mark. */
export function Swatch({ tone: i, mark = "line", fill }: { tone: number; mark?: LegendItem["mark"]; fill?: string }) {
  const t = tone(i);
  if (mark === "line") {
    return (
      <svg width="16" height="6" aria-hidden className="shrink-0">
        <line x1="1.5" y1="3" x2="14.5" y2="3" stroke={t.stroke} strokeWidth="2" strokeDasharray={t.dash} strokeLinecap="round" />
      </svg>
    );
  }
  const popout = i === 0 && !fill;
  if (mark === "dot" && i % 2 === 1) {
    return <span aria-hidden className="size-2 shrink-0 rounded-full border-[1.5px]" style={{ borderColor: t.stroke }} />;
  }
  return (
    <span
      aria-hidden
      className={cn("size-2 shrink-0", mark === "dot" ? "rounded-full" : "rounded-[2.5px]")}
      style={{ background: fill && !fill.startsWith("url(") ? fill : popout || fill ? POPOUT_CSS : t.fill }}
    />
  );
}

/** The popout gradient, for one SVG. */
export function PopoutGradient({ id, horizontal = false }: { id: string; horizontal?: boolean }) {
  return (
    <linearGradient id={id} x1="0" y1="0" x2={horizontal ? "1" : "0"} y2={horizontal ? "0" : "1"}>
      <stop offset="0%" stopColor={horizontal ? "#d9d9d9" : "#f5f5f5"} />
      <stop offset="100%" stopColor={horizontal ? "#f5f5f5" : "#d9d9d9"} />
    </linearGradient>
  );
}

export default ChartCard;

"use client";

import { useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { Swatch, type LegendItem } from "./ChartCard";

// A small raised pill that follows the active point. It sits above the anchor and slides along
// the plot, clamped inside it; it fades in and out without scaling.

export interface TooltipRow {
  label: ReactNode;
  value: ReactNode;
  tone: number;
  mark?: LegendItem["mark"];
  fill?: string;
}

export interface ChartTooltipProps {
  open: boolean;
  /** Anchor in the plot's pixel space. */
  x: number;
  y: number;
  /** Plot width, to keep the pill inside. */
  bound: number;
  title?: ReactNode;
  rows: TooltipRow[];
}

export function ChartTooltip({ open, x, y, bound, title, rows }: ChartTooltipProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [w, setW] = useState(140);
  useLayoutEffect(() => {
    if (ref.current) setW(ref.current.offsetWidth);
  });
  const left = Math.min(Math.max(x - w / 2, 4), Math.max(4, bound - w - 4));

  return (
    <div
      ref={ref}
      aria-hidden
      className="pointer-events-none absolute z-10 min-w-[128px] rounded-lg border border-white/[0.08] bg-[linear-gradient(180deg,#1b1b1d_0%,#151516_100%)] px-2.5 py-2 text-xs shadow-[inset_0_1.5px_0_0_rgba(255,255,255,0.08),inset_0_-1px_0_0_rgba(0,0,0,0.5),0_14px_30px_-10px_rgba(0,0,0,0.5),0_1px_4px_-1px_rgba(0,0,0,0.35)] transition-[left,top,opacity] duration-150 ease-[cubic-bezier(0.32,0.72,0,1)] motion-reduce:transition-opacity"
      style={{ left, top: y, opacity: open ? 1 : 0, transform: "translateY(calc(-100% - 10px))" }}
    >
      {title != null && <div className="mb-1.5 whitespace-nowrap text-[11px] text-neutral-500">{title}</div>}
      <div className="flex flex-col gap-1">
        {rows.map((row, i) => (
          <div key={i} className="flex items-center gap-2 whitespace-nowrap">
            <Swatch tone={row.tone} mark={row.mark} fill={row.fill} />
            <span className="text-neutral-400">{row.label}</span>
            <span className="ml-auto pl-4 font-medium tabular-nums text-neutral-100">{row.value}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

export default ChartTooltip;

"use client";

import { forwardRef, useId, type PointerEvent } from "react";
import { ChartCard, ChartTray, type ChartCardProps } from "./ChartCard";
import { ChartTooltip } from "./ChartTooltip";
import { XLabels, YGrid, labelWidth } from "./axes";
import { useActiveIndex, useTween, useWidth } from "./hooks";
import { areaPath, compact, linear, linePath, niceDomain, num, smoothPath, tone, type Pt } from "./scale";

// Lines over time, lit from above. The first series is the popout line, the lightest thing in the
// plot; the others step down in luminance and dash. The area variant hangs a soft white wash under
// each line (lighting, not decoration). A crosshair with pearls follows the pointer or the arrow
// keys. On mount the lines rise from the baseline; on new data they glide.

export type Datum = Record<string, string | number | null | undefined>;

export interface ChartSeries {
  /** The field in each datum that holds this series' value. */
  key: string;
  label: string;
  /** Luminance step, 0 (popout) to 3. Defaults to the series' index, so colour follows the entity. */
  tone?: number;
}

export interface LineChartProps extends Omit<ChartCardProps, "legend" | "table" | "children"> {
  data: Datum[];
  series: ChartSeries[];
  /** The field holding each point's category or time label. */
  xKey: string;
  variant?: "line" | "area";
  curve?: "linear" | "smooth";
  /** Plot height in px. Default 180. */
  height?: number;
  grid?: boolean;
  legend?: boolean;
  tooltip?: boolean;
  /** A pearl on the last point of the first series. Default true. */
  endMarker?: boolean;
  yMin?: number;
  yMax?: number;
  formatValue?: (value: number) => string;
  formatX?: (x: string | number) => string;
  animateOnMount?: boolean;
}

const PAD = { r: 14, t: 16, b: 28 };

export const LineChart = forwardRef<HTMLDivElement, LineChartProps>(function LineChart(
  {
    data,
    series,
    xKey,
    variant = "line",
    curve = "smooth",
    height = 180,
    grid = true,
    legend = true,
    tooltip = true,
    endMarker = true,
    yMin,
    yMax,
    formatValue = compact,
    formatX = String,
    animateOnMount = true,
    ...card
  },
  ref
) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const [plotRef, width] = useWidth<HTMLDivElement>();
  const n = data.length;
  const raw = series.flatMap((s) => data.map((d) => num(d[s.key])));
  const shown = useTween(raw, animateOnMount);
  const { active, setActive, focusProps } = useActiveIndex(n);

  const dataMin = raw.length ? Math.min(...raw) : 0;
  const dataMax = raw.length ? Math.max(...raw) : 1;
  const floor = yMin ?? (variant === "area" || (dataMin >= 0 && dataMin <= dataMax * 0.4) ? Math.min(0, dataMin) : dataMin);
  const { min, max, ticks } = niceDomain(floor, yMax ?? dataMax, height < 140 ? 3 : 4);

  const padL = labelWidth(ticks.map(formatValue));
  const iw = Math.max(1, width - padL - PAD.r);
  const xAt = (i: number) => padL + (n <= 1 ? iw / 2 : (i / (n - 1)) * iw);
  const yAt = linear(min, max, height - PAD.b, PAD.t);
  const smooth = curve === "smooth";
  const points = (si: number): Pt[] => data.map((_, i) => [xAt(i), yAt(shown[si * n + i])]);

  const onPointer = (e: PointerEvent<SVGRectElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const i = Math.round(((e.clientX - rect.left) / rect.width) * (n - 1));
    setActive(Math.min(Math.max(i, 0), n - 1));
  };

  const toneOf = (si: number) => series[si].tone ?? si;
  const labelId = `${uid}-label`;

  return (
    <ChartCard
      {...card}
      ref={ref}
      labelId={labelId}
      legend={legend && series.length > 1 ? series.map((s, si) => ({ label: s.label, tone: toneOf(si) })) : undefined}
      table={{
        columns: [xKey, ...series.map((s) => s.label)],
        rows: data.map((d) => [formatX(d[xKey] ?? ""), ...series.map((s) => formatValue(num(d[s.key])))]),
      }}
    >
      <ChartTray ref={plotRef} style={{ height }} role="img" aria-labelledby={card.label ? labelId : undefined} {...focusProps}>
        {width > 0 && (
          <svg width={width} height={height} className="absolute inset-0 block overflow-visible">
            <defs>
              {series.map((s, si) => (
                <linearGradient key={s.key} id={`${uid}-a${si}`} x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#fff" stopOpacity={tone(toneOf(si)).area} />
                  <stop offset="100%" stopColor="#fff" stopOpacity="0" />
                </linearGradient>
              ))}
            </defs>

            <YGrid ticks={ticks} y={yAt} x0={padL} x1={width - PAD.r} format={formatValue} grid={grid} />
            <XLabels labels={data.map((d) => formatX(d[xKey] ?? ""))} x={xAt} y={height - 10} width={iw} />

            {/* Later series underneath, so the popout line is always on top. */}
            {series
              .map((s, si) => ({ s, si }))
              .reverse()
              .map(({ s, si }) => {
                const t = tone(toneOf(si));
                const pts = points(si);
                return (
                  <g key={s.key}>
                    {variant === "area" && <path d={areaPath(pts, yAt(Math.max(min, Math.min(0, max))), smooth)} fill={`url(#${uid}-a${si})`} />}
                    <path
                      d={smooth ? smoothPath(pts) : linePath(pts)}
                      fill="none"
                      stroke={t.stroke}
                      strokeWidth={toneOf(si) === 0 ? 2 : 1.5}
                      strokeDasharray={t.dash}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </g>
                );
              })}

            {endMarker && active == null && n > 0 && series.length > 0 && (
              <Pearl x={xAt(n - 1)} y={yAt(shown[n - 1])} tone={toneOf(0)} />
            )}

            {active != null && (
              <g>
                <line
                  x1={Math.round(xAt(active)) + 0.5}
                  x2={Math.round(xAt(active)) + 0.5}
                  y1={PAD.t - 6}
                  y2={height - PAD.b}
                  stroke="rgba(255,255,255,0.12)"
                />
                {series.map((s, si) => (
                  <Pearl key={s.key} x={xAt(active)} y={yAt(shown[si * n + active])} tone={toneOf(si)} />
                ))}
              </g>
            )}

            <rect
              x={padL}
              y={0}
              width={iw}
              height={height}
              fill="transparent"
              onPointerMove={onPointer}
              onPointerDown={onPointer}
              onPointerLeave={() => setActive(null)}
            />
          </svg>
        )}
        {tooltip && width > 0 && (
          <ChartTooltip
            open={active != null}
            x={xAt(active ?? n - 1)}
            y={Math.min(...series.map((_, si) => yAt(num(data[active ?? n - 1]?.[series[si].key]))), height)}
            bound={width}
            title={formatX(data[active ?? n - 1]?.[xKey] ?? "")}
            rows={series.map((s, si) => ({
              label: s.label,
              value: formatValue(num(data[active ?? n - 1]?.[s.key])),
              tone: toneOf(si),
            }))}
          />
        )}
      </ChartTray>
    </ChartCard>
  );
});

/** A data point: a popout pearl seated in a ring of the tray's colour; hollow for later series. */
export function Pearl({ x, y, tone: i, r = 3.5 }: { x: number; y: number; tone: number; r?: number }) {
  const t = tone(i);
  return (
    <g aria-hidden>
      <circle cx={x} cy={y} r={r + 2.5} fill="#0c0c0d" />
      {i === 0 ? (
        <circle cx={x} cy={y} r={r} fill="#f0f0f0" />
      ) : (
        <circle cx={x} cy={y} r={r - 0.75} fill="#0c0c0d" stroke={t.stroke} strokeWidth="1.5" />
      )}
    </g>
  );
}

/** LineChart with the area variant. */
export const AreaChart = forwardRef<HTMLDivElement, Omit<LineChartProps, "variant">>(function AreaChart(props, ref) {
  return <LineChart {...props} ref={ref} variant="area" />;
});

export default LineChart;

"use client";

import { forwardRef, useId, type PointerEvent } from "react";
import { cn } from "@/lib/utils";
import { ChartCard, ChartTray, PopoutGradient, Swatch, type ChartCardProps } from "./ChartCard";
import { ChartTooltip } from "./ChartTooltip";
import { XLabels, YGrid, labelWidth } from "./axes";
import { useActiveIndex, useTween, useWidth } from "./hooks";
import type { ChartSeries, Datum } from "./LineChart";
import { barPath, compact, linear, niceDomain, num, tone } from "./scale";

// Bars as machined parts. Each bar sits in a slot cut into the tray, and the value rises out of it
// as a popout part with a rounded data end; zero stays a firm cut line, and negatives hang below
// it. Grouped bars stand side by side; stacked segments are split by 2px cuts. Horizontal bars
// become a ranked list: label and value on one line, a recessed track with its fill underneath.
// Hovering a category dims the rest.

export interface BarChartProps extends Omit<ChartCardProps, "legend" | "table" | "children"> {
  data: Datum[];
  series: ChartSeries[];
  xKey: string;
  orientation?: "vertical" | "horizontal";
  stacked?: boolean;
  /** Show the recessed slot behind each bar. Default true. */
  slots?: boolean;
  /** Plot height in px for vertical bars. Default 180. */
  height?: number;
  grid?: boolean;
  legend?: boolean;
  tooltip?: boolean;
  formatValue?: (value: number) => string;
  formatX?: (x: string | number) => string;
  animateOnMount?: boolean;
}

const PAD = { r: 10, t: 14, b: 28 };
const GAP = 2;
const RADIUS = 4;
const POPOUT_CSS = "linear-gradient(180deg,#f5f5f5 0%,#d9d9d9 100%)";

export const BarChart = forwardRef<HTMLDivElement, BarChartProps>(function BarChart(
  {
    data,
    series,
    xKey,
    orientation = "vertical",
    stacked = false,
    slots = true,
    height = 180,
    grid = true,
    legend = true,
    tooltip = true,
    formatValue = compact,
    formatX = String,
    animateOnMount = true,
    ...card
  },
  ref
) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const labelId = `${uid}-label`;
  const [plotRef, width] = useWidth<HTMLDivElement>();
  const n = data.length;
  const m = series.length;
  const raw = series.flatMap((s) => data.map((d) => num(d[s.key])));
  const shown = useTween(raw, animateOnMount);
  const { active, setActive, focusProps } = useActiveIndex(n);
  const toneOf = (si: number) => series[si].tone ?? si;
  const val = (si: number, i: number) => shown[si * n + i];
  const target = (si: number, i: number) => raw[si * n + i];

  const sums = data.map((_, i) => series.reduce((acc, __, si) => acc + Math.max(0, target(si, i)), 0));
  const negs = data.map((_, i) => series.reduce((acc, __, si) => acc + Math.min(0, target(si, i)), 0));
  const hi = stacked ? Math.max(0, ...sums) : Math.max(0, ...raw);
  const lo = stacked ? Math.min(0, ...negs) : Math.min(0, ...raw);

  const shared = {
    ...card,
    ref,
    labelId,
    legend: legend && m > 1 ? series.map((s, si) => ({ label: s.label, tone: toneOf(si), mark: "bar" as const })) : undefined,
    table: {
      columns: [xKey, ...series.map((s) => s.label)],
      rows: data.map((d) => [formatX(d[xKey] ?? ""), ...series.map((s) => formatValue(num(d[s.key])))]),
    },
  };

  if (orientation === "horizontal") {
    const top = hi || 1;
    return (
      <ChartCard {...shared}>
        <ChartTray
          className="px-4 py-3.5"
          role="list"
          aria-labelledby={card.label ? labelId : undefined}
          {...focusProps}
          onPointerLeave={() => setActive(null)}
        >
          <div className="flex flex-col gap-3">
            {data.map((d, i) => (
              <div
                key={i}
                role="listitem"
                onPointerEnter={() => setActive(i)}
                className={cn(
                  "transition-opacity duration-150",
                  active != null && active !== i && "opacity-45"
                )}
              >
                <div className="flex items-baseline justify-between gap-3 text-xs">
                  <span className={cn("truncate transition-colors duration-150", active === i ? "text-neutral-100" : "text-neutral-400")}>
                    {formatX(d[xKey] ?? "")}
                  </span>
                  <span className="flex shrink-0 items-center gap-2.5 font-medium tabular-nums text-neutral-100">
                    {stacked ? (
                      formatValue(sums[i])
                    ) : (
                      series.map((s, si) => (
                        <span key={s.key} className="flex items-center gap-1.5">
                          {m > 1 && <Swatch tone={toneOf(si)} mark="bar" />}
                          <span className={si > 0 ? "text-neutral-400" : undefined}>{formatValue(target(si, i))}</span>
                        </span>
                      ))
                    )}
                  </span>
                </div>
                {(stacked ? [0] : series.map((_, si) => si)).map((si) => (
                  <div
                    key={si}
                    className="relative mt-1.5 h-1.5 overflow-hidden rounded-full bg-[#070707] shadow-[inset_0_1px_2px_rgba(0,0,0,0.9),0_1px_0_rgba(255,255,255,0.05)]"
                  >
                    {stacked ? (
                      (() => {
                        let acc = 0;
                        const last = series.reduce((l, _, k) => (val(k, i) > 0 ? k : l), -1);
                        return series.map((s, k) => {
                          const v = Math.max(0, val(k, i));
                          const left = (acc / top) * 100;
                          acc += v;
                          const cut = k > 0 ? GAP : 0;
                          return (
                            <span
                              key={s.key}
                              className={cn("absolute inset-y-0", k === last && "rounded-r-full")}
                              style={{
                                left: `calc(${left}% + ${cut}px)`,
                                width: `max(0px, calc(${(v / top) * 100}% - ${cut}px))`,
                                background: toneOf(k) === 0 ? POPOUT_CSS : tone(toneOf(k)).fill,
                              }}
                            />
                          );
                        });
                      })()
                    ) : (
                      <span
                        className="absolute inset-y-0 left-0 rounded-full"
                        style={{
                          width: `${(Math.max(0, val(si, i)) / top) * 100}%`,
                          background: toneOf(si) === 0 ? POPOUT_CSS : tone(toneOf(si)).fill,
                        }}
                      />
                    )}
                  </div>
                ))}
              </div>
            ))}
          </div>
        </ChartTray>
      </ChartCard>
    );
  }

  const { min, max, ticks } = niceDomain(lo, hi, height < 140 ? 3 : 4);
  const padL = labelWidth(ticks.map(formatValue));
  const iw = Math.max(1, width - padL - PAD.r);
  const bw = iw / Math.max(1, n);
  const yAt = linear(min, max, height - PAD.b, PAD.t);
  const y0 = yAt(0);
  const gap = 3;
  const barW = stacked
    ? Math.min(Math.max(bw * 0.5, 6), 28)
    : Math.min(Math.max((bw * 0.64 - (m - 1) * gap) / Math.max(1, m), 3), 16);
  const groupW = stacked ? barW : m * barW + (m - 1) * gap;
  const center = (i: number) => padL + bw * i + bw / 2;
  const barX = (i: number, si: number) => center(i) - groupW / 2 + (stacked ? 0 : si * (barW + gap));
  const fill = (si: number) => (toneOf(si) === 0 ? `url(#${uid}-pop)` : tone(toneOf(si)).fill);
  const slotPath = (x: number) => barPath(x, PAD.t, barW, height - PAD.b - PAD.t, Math.min(RADIUS, barW / 2) + 1, "none");

  const onPointer = (e: PointerEvent<SVGRectElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    setActive(Math.min(Math.max(Math.floor(((e.clientX - rect.left) / rect.width) * n), 0), n - 1));
  };

  const bars = (i: number) => {
    if (!stacked) {
      return series.map((s, si) => {
        const v = val(si, i);
        const y1 = yAt(v);
        const x = barX(i, si);
        return (
          <path
            key={s.key}
            d={v >= 0 ? barPath(x, y1, barW, y0 - y1, RADIUS, "top") : barPath(x, y0, barW, y1 - y0, RADIUS, "bottom")}
            fill={fill(si)}
          />
        );
      });
    }
    let pos = 0;
    let neg = 0;
    const topPos = series.reduce((l, _, k) => (val(k, i) > 0 ? k : l), -1);
    const topNeg = series.reduce((l, _, k) => (val(k, i) < 0 ? k : l), -1);
    return series.map((s, si) => {
      const v = val(si, i);
      const x = barX(i, si);
      if (v >= 0) {
        const yb = yAt(pos) - (pos > 0 ? GAP : 0);
        pos += v;
        const yt = yAt(pos);
        return <path key={s.key} d={barPath(x, yt, barW, yb - yt, RADIUS, si === topPos ? "top" : "none")} fill={fill(si)} />;
      }
      const yt = yAt(neg) + (neg < 0 ? GAP : 0);
      neg += v;
      const yb = yAt(neg);
      return <path key={s.key} d={barPath(x, yt, barW, yb - yt, RADIUS, si === topNeg ? "bottom" : "none")} fill={fill(si)} />;
    });
  };

  const anchor = active ?? 0;
  const anchorTop = stacked ? sums[anchor] : Math.max(0, ...series.map((_, si) => target(si, anchor)));

  return (
    <ChartCard {...shared}>
      <ChartTray ref={plotRef} style={{ height }} role="img" aria-labelledby={card.label ? labelId : undefined} {...focusProps}>
        {width > 0 && (
          <svg width={width} height={height} className="absolute inset-0 block overflow-visible">
            <defs>
              <PopoutGradient id={`${uid}-pop`} />
            </defs>
            <YGrid ticks={ticks} y={yAt} x0={padL} x1={width - PAD.r} format={formatValue} grid={grid} />
            <XLabels labels={data.map((d) => formatX(d[xKey] ?? ""))} x={center} y={height - 10} width={iw} minGap={40} edgeAlign={false} />

            {active != null && (
              <rect x={padL + bw * active + 2} y={PAD.t - 8} width={bw - 4} height={height - PAD.b - PAD.t + 12} rx="8" fill="rgba(255,255,255,0.025)" />
            )}

            {data.map((_, i) => (
              <g
                key={i}
                className="transition-opacity duration-150"
                style={{ opacity: active != null && active !== i ? 0.4 : 1 }}
              >
                {slots && (stacked ? [0] : series.map((_, si) => si)).map((si) => <path key={si} d={slotPath(barX(i, si))} fill="#070707" />)}
                {bars(i)}
              </g>
            ))}

            <line x1={padL} x2={width - PAD.r} y1={Math.round(y0) + 0.5} y2={Math.round(y0) + 0.5} stroke="rgba(255,255,255,0.1)" />

            <rect
              x={padL}
              y={0}
              width={iw}
              height={height}
              fill="transparent"
              onPointerMove={onPointer}
              onPointerDown={onPointer}
              onPointerLeave={() => setActive(null)}
            />
          </svg>
        )}
        {tooltip && width > 0 && (
          <ChartTooltip
            open={active != null}
            x={center(anchor)}
            y={yAt(anchorTop) - 4}
            bound={width}
            title={formatX(data[anchor]?.[xKey] ?? "")}
            rows={series.map((s, si) => ({ label: s.label, value: formatValue(target(si, anchor)), tone: toneOf(si), mark: "bar" as const }))}
          />
        )}
      </ChartTray>
    </ChartCard>
  );
});

export default BarChart;

"use client";

import { forwardRef, useId, useState, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { ChartCard, ChartTray, PopoutGradient, Swatch, type ChartCardProps } from "./ChartCard";
import { useTween, useWidth } from "./hooks";
import { compact, ringSegment, sliceFill } from "./scale";

// Parts of a whole, as a ring of machined segments in a recessed socket. The first slice is
// popout and the rest step down in luminance, split by 2px cuts. The total sits in a sunken face
// in the middle; hovering or focusing a slice (in the ring or the list) lifts it out by 3px and
// puts its numbers in the face. On mount the ring sweeps round from twelve o'clock.

export interface DonutDatum {
  label: string;
  value: number;
}

export interface DonutChartProps extends Omit<ChartCardProps, "legend" | "table" | "children"> {
  /** Slices, in the order they should run. Put the largest first so it gets the popout. */
  data: DonutDatum[];
  variant?: "donut" | "pie";
  /** Ring diameter in px. Default 168. */
  diameter?: number;
  /** Ring thickness in px. Default 20. */
  thickness?: number;
  /** Shown in the face when nothing is active. Default: the formatted total. */
  centerValue?: ReactNode;
  /** Under the centre value. Default "Total". */
  centerLabel?: ReactNode;
  /** The list of slices beside the ring. Default true. */
  legend?: boolean;
  formatValue?: (value: number) => string;
  animateOnMount?: boolean;
}

const pct = (v: number, total: number) => `${total ? Math.round((v / total) * 1000) / 10 : 0}%`;

export const DonutChart = forwardRef<HTMLDivElement, DonutChartProps>(function DonutChart(
  {
    data,
    variant = "donut",
    diameter = 168,
    thickness = 20,
    centerValue,
    centerLabel = "Total",
    legend = true,
    formatValue = compact,
    animateOnMount = true,
    ...card
  },
  ref
) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const labelId = `${uid}-label`;
  const [trayRef, width] = useWidth<HTMLDivElement>();
  const [active, setActive] = useState<number | null>(null);
  const raw = data.map((d) => Math.max(0, d.value));
  const values = useTween(raw, false);
  const [sweep] = useTween([1], animateOnMount, 1);
  const total = values.reduce((a, b) => a + b, 0);
  const targetTotal = raw.reduce((a, b) => a + b, 0);
  const side = width === 0 || width >= 340;

  const D = diameter;
  const c = D / 2;
  const r1 = c - 4;
  const r0 = variant === "pie" ? 0 : Math.max(8, r1 - thickness);
  const gapDeg = ((2 / Math.max(12, (r0 + r1) / 2)) * 180) / Math.PI;

  let a = 0;
  const slices = values.map((v, i) => {
    const span = total ? (v / total) * 360 * sweep : 0;
    const start = a;
    a += span;
    return { i, start, span };
  });

  const face = active == null
    ? { value: centerValue ?? formatValue(targetTotal), label: centerLabel }
    : { value: pct(raw[active], targetTotal), label: data[active]?.label };

  return (
    <ChartCard
      {...card}
      ref={ref}
      labelId={labelId}
      table={{ columns: ["Slice", "Value", "Share"], rows: data.map((d) => [d.label, formatValue(d.value), pct(d.value, targetTotal)]) }}
    >
      <ChartTray ref={trayRef} className={cn("flex items-center gap-5 p-4", side ? "flex-row" : "flex-col")}>
        <div className="relative shrink-0" style={{ width: D, height: D }}>
          <svg
            width={D}
            height={D}
            className="block overflow-visible"
            role="img"
            aria-labelledby={card.label ? labelId : undefined}
            onPointerLeave={() => setActive(null)}
          >
            <defs>
              <PopoutGradient id={`${uid}-pop`} />
            </defs>
            {/* The socket the ring sits in. */}
            <path d={ringSegment(c, c, r0, r1, 0, 360)} fill="#070707" />
            {slices.map(({ i, start, span }) => {
              if (span <= gapDeg) return null;
              const lift = active === i ? 3 : 0;
              return (
                <path
                  key={i}
                  d={ringSegment(c, c, r0 && r0 + lift * 0.3, r1 + lift, start + gapDeg / 2, start + span - gapDeg / 2)}
                  fill={sliceFill(i, `${uid}-pop`)}
                  className="transition-opacity duration-150"
                  style={{ opacity: active != null && active !== i ? 0.45 : 1 }}
                  onPointerEnter={() => setActive(i)}
                />
              );
            })}
            {r0 > 0 && (
              <circle cx={c} cy={c} r={Math.max(0, r0 - 7)} fill="#070707" stroke="rgba(255,255,255,0.04)" />
            )}
          </svg>
          {r0 > 0 && (
            <div aria-hidden className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center text-center">
              <span className="text-[22px] font-semibold leading-none tracking-[-0.04em] text-neutral-100 tabular-nums">{face.value}</span>
              <span className="mt-1.5 max-w-[60%] truncate text-[11px] text-neutral-500">{face.label}</span>
            </div>
          )}
        </div>

        {legend && (
          <ul className={cn("flex min-w-0 flex-col gap-0.5", side ? "flex-1" : "w-full")}>
            {data.map((d, i) => (
              <li key={i}>
                <button
                  type="button"
                  onPointerEnter={() => setActive(i)}
                  onPointerLeave={() => setActive(null)}
                  onFocus={() => setActive(i)}
                  onBlur={() => setActive(null)}
                  className={cn(
                    "flex h-8 w-full items-center gap-2.5 rounded-lg px-2 text-left text-xs outline-none transition-colors duration-150",
                    "focus-visible:outline focus-visible:outline-1 focus-visible:outline-offset-2 focus-visible:outline-white/40",
                    active === i ? "bg-white/[0.03] text-neutral-100" : "text-neutral-400"
                  )}
                >
                  <Swatch tone={i} mark="bar" fill={sliceFill(i, `${uid}-pop`)} />
                  <span className="min-w-0 flex-1 truncate">{d.label}</span>
                  <span className="font-medium tabular-nums text-neutral-100">{formatValue(d.value)}</span>
                  <span className="w-10 text-right tabular-nums text-neutral-500">{pct(d.value, targetTotal)}</span>
                </button>
              </li>
            ))}
          </ul>
        )}
      </ChartTray>
    </ChartCard>
  );
});

export default DonutChart;

"use client";

import { forwardRef, useId, type PointerEvent } from "react";
import { ChartCard, ChartTray, type ChartCardProps } from "./ChartCard";
import { ChartTooltip } from "./ChartTooltip";
import { useActiveIndex, useTween, useWidth } from "./hooks";
import { Pearl, type ChartSeries, type Datum } from "./LineChart";
import { compact, linePath, niceDomain, num, polar, tone, type Pt } from "./scale";

// Several measures around a circle, one polygon per series. The web is cut faintly into the tray;
// the first series is a popout outline over a faint wash, later ones are dashed. Pointing at a
// spoke (or arrowing to it) brightens it, seats pearls on every series and opens the tooltip.

export interface RadarChartProps extends Omit<ChartCardProps, "legend" | "table" | "children"> {
  /** One datum per axis. */
  data: Datum[];
  series: ChartSeries[];
  /** The field holding each axis' name. */
  xKey: string;
  /** Top of the scale. Default: the data's maximum, rounded up. */
  max?: number;
  /** Rings in the web. Default 4. */
  levels?: number;
  /** Plot height in px. Default 248. */
  height?: number;
  legend?: boolean;
  tooltip?: boolean;
  formatValue?: (value: number) => string;
  animateOnMount?: boolean;
}

export const RadarChart = forwardRef<HTMLDivElement, RadarChartProps>(function RadarChart(
  {
    data,
    series,
    xKey,
    max: maxProp,
    levels = 4,
    height = 248,
    legend = true,
    tooltip = true,
    formatValue = compact,
    animateOnMount = true,
    ...card
  },
  ref
) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const labelId = `${uid}-label`;
  const [plotRef, width] = useWidth<HTMLDivElement>();
  const n = data.length;
  const raw = series.flatMap((s) => data.map((d) => num(d[s.key])));
  const shown = useTween(raw, animateOnMount);
  const { active, setActive, focusProps } = useActiveIndex(n);
  const toneOf = (si: number) => series[si].tone ?? si;

  const top = maxProp ?? niceDomain(0, Math.max(1, ...raw), levels).max;
  const cx = width / 2;
  const cy = height / 2 + 2;
  const R = Math.max(10, Math.min(width / 2 - 64, height / 2 - 30));
  const step = 360 / Math.max(1, n);
  const at = (i: number, v: number): Pt => polar(cx, cy, (Math.max(0, v) / top) * R, i * step);
  const ring = (f: number) => `${linePath(data.map((_, i) => polar(cx, cy, R * f, i * step)))}Z`;

  const onPointer = (e: PointerEvent<SVGRectElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const dx = e.clientX - rect.left - cx;
    const dy = e.clientY - rect.top - cy;
    if (Math.hypot(dx, dy) < 8) return;
    const deg = ((Math.atan2(dx, -dy) * 180) / Math.PI + 360) % 360;
    setActive(Math.round(deg / step) % n);
  };

  const anchor = active ?? 0;
  const [tx, ty] = polar(cx, cy, R + 6, anchor * step);

  return (
    <ChartCard
      {...card}
      ref={ref}
      labelId={labelId}
      legend={legend && series.length > 1 ? series.map((s, si) => ({ label: s.label, tone: toneOf(si) })) : undefined}
      table={{
        columns: [xKey, ...series.map((s) => s.label)],
        rows: data.map((d) => [String(d[xKey] ?? ""), ...series.map((s) => formatValue(num(d[s.key])))]),
      }}
    >
      <ChartTray ref={plotRef} style={{ height }} role="img" aria-labelledby={card.label ? labelId : undefined} {...focusProps}>
        {width > 0 && n > 2 && (
          <svg width={width} height={height} className="absolute inset-0 block overflow-visible">
            <g aria-hidden>
              {Array.from({ length: levels }, (_, l) => (
                <path
                  key={l}
                  d={ring((l + 1) / levels)}
                  fill={l === levels - 1 ? "#070707" : "none"}
                  fillOpacity={l === levels - 1 ? 0.6 : undefined}
                  stroke={l === levels - 1 ? "rgba(255,255,255,0.09)" : "rgba(255,255,255,0.05)"}
                />
              ))}
              {data.map((d, i) => {
                const [x, y] = polar(cx, cy, R, i * step);
                const [lx, ly] = polar(cx, cy, R + 16, i * step);
                const s = Math.sin((i * step * Math.PI) / 180);
                const cosv = Math.cos((i * step * Math.PI) / 180);
                return (
                  <g key={i}>
                    <line
                      x1={cx}
                      y1={cy}
                      x2={x}
                      y2={y}
                      stroke={active === i ? "rgba(255,255,255,0.2)" : "rgba(255,255,255,0.05)"}
                      className="transition-[stroke] duration-150"
                    />
                    <text
                      x={lx}
                      y={ly}
                      textAnchor={s > 0.3 ? "start" : s < -0.3 ? "end" : "middle"}
                      dominantBaseline={cosv > 0.5 ? "auto" : cosv < -0.5 ? "hanging" : "middle"}
                      fill={active === i ? "rgb(245 245 245)" : "rgb(115 115 115)"}
                      style={{ fontSize: 10.5 }}
                      className="transition-[fill] duration-150"
                    >
                      {String(d[xKey] ?? "")}
                    </text>
                  </g>
                );
              })}
            </g>

            {series
              .map((s, si) => ({ s, si }))
              .reverse()
              .map(({ s, si }) => {
                const t = tone(toneOf(si));
                const pts = data.map((_, i) => at(i, shown[si * n + i]));
                const lead = toneOf(si) === 0;
                return (
                  <g key={s.key}>
                    <path
                      d={`${linePath(pts)}Z`}
                      fill="#fff"
                      fillOpacity={lead ? 0.07 : t.area * 0.6}
                      stroke={t.stroke}
                      strokeWidth={lead ? 1.75 : 1.5}
                      strokeDasharray={t.dash}
                      strokeLinejoin="round"
                    />
                    {lead && active == null && pts.map(([x, y], i) => <circle key={i} cx={x} cy={y} r="2.25" fill="#ededed" />)}
                  </g>
                );
              })}

            {active != null &&
              series.map((s, si) => {
                const [x, y] = at(active, shown[si * n + active]);
                return <Pearl key={s.key} x={x} y={y} tone={toneOf(si)} />;
              })}

            <rect
              width={width}
              height={height}
              fill="transparent"
              onPointerMove={onPointer}
              onPointerDown={onPointer}
              onPointerLeave={() => setActive(null)}
            />
          </svg>
        )}
        {tooltip && width > 0 && n > 2 && (
          <ChartTooltip
            open={active != null}
            x={tx}
            y={Math.min(ty, cy) - 6}
            bound={width}
            title={String(data[anchor]?.[xKey] ?? "")}
            rows={series.map((s, si) => ({ label: s.label, value: formatValue(raw[si * n + anchor]), tone: toneOf(si) }))}
          />
        )}
      </ChartTray>
    </ChartCard>
  );
});

export default RadarChart;

"use client";

import { forwardRef, useId, useState, type PointerEvent } from "react";
import { ChartCard, ChartTray, type ChartCardProps } from "./ChartCard";
import { ChartTooltip } from "./ChartTooltip";
import { XLabels, YGrid, labelWidth } from "./axes";
import { useTween, useWidth } from "./hooks";
import { clamp, compact, linear, niceDomain, tone } from "./scale";

// Two measures against each other, one pearl per record. The first series is solid popout
// pearls, the second hollow rings, later ones smaller and dimmer, and each pearl sits in a 2px ring
// of the tray's colour so overlaps stay legible. A third value can size the pearls (bubbles).
// The nearest pearl to the pointer lifts, with dashed guides back to both axes.

export interface ScatterPoint {
  x: number;
  y: number;
  /** Sizes the pearl when the chart has a size channel. */
  z?: number;
  label?: string;
}

export interface ScatterSeries {
  key: string;
  label: string;
  tone?: number;
  points: ScatterPoint[];
}

export interface ScatterChartProps extends Omit<ChartCardProps, "legend" | "table" | "children"> {
  series: ScatterSeries[];
  xLabel?: string;
  yLabel?: string;
  /** Label for the size channel in the tooltip. */
  zLabel?: string;
  height?: number;
  grid?: boolean;
  legend?: boolean;
  tooltip?: boolean;
  formatX?: (v: number) => string;
  formatY?: (v: number) => string;
  formatZ?: (v: number) => string;
  animateOnMount?: boolean;
}

const PAD = { r: 14, t: 14, b: 28 };

export const ScatterChart = forwardRef<HTMLDivElement, ScatterChartProps>(function ScatterChart(
  {
    series,
    xLabel = "x",
    yLabel = "y",
    zLabel = "size",
    height = 200,
    grid = true,
    legend = true,
    tooltip = true,
    formatX = compact,
    formatY = compact,
    formatZ = compact,
    animateOnMount = true,
    ...card
  },
  ref
) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const labelId = `${uid}-label`;
  const [plotRef, width] = useWidth<HTMLDivElement>();
  const all = series.flatMap((s, si) => s.points.map((p, pi) => ({ ...p, si, pi })));
  const coords = useTween(all.flatMap((p) => [p.x, p.y]), false);
  const [grow] = useTween([1], animateOnMount, 1.1);
  const toneOf = (si: number) => series[si].tone ?? si;

  const xs = all.map((p) => p.x);
  const ys = all.map((p) => p.y);
  const zs = all.map((p) => p.z ?? 0);
  const xd = niceDomain(Math.min(...xs, 0), Math.max(...xs, 1), 5);
  const yd = niceDomain(Math.min(...ys, 0), Math.max(...ys, 1), 4);
  const zMax = Math.max(...zs, 0);
  const radius = (z: number | undefined, si: number) =>
    zMax > 0 && z != null ? 3.5 + Math.sqrt(z / zMax) * 7.5 : toneOf(si) >= 2 ? 3 : 4;

  const padL = labelWidth(yd.ticks.map(formatY));
  const iw = Math.max(1, width - padL - PAD.r);
  const xAt = linear(xd.min, xd.max, padL, padL + iw);
  const yAt = linear(yd.min, yd.max, height - PAD.b, PAD.t);
  const xTicks = xd.ticks;

  const [activeKey, setActiveKey] = useState<number | null>(null);
  const active = activeKey == null ? null : all[activeKey] ?? null;

  const onPointer = (e: PointerEvent<SVGRectElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const px = e.clientX - rect.left;
    const py = e.clientY - rect.top;
    let best = -1;
    let bestD = 28;
    all.forEach((_, k) => {
      const d = Math.hypot(xAt(coords[k * 2]) - px, yAt(coords[k * 2 + 1]) - py);
      if (d < bestD) {
        bestD = d;
        best = k;
      }
    });
    setActiveKey(best < 0 ? null : best);
  };

  return (
    <ChartCard
      {...card}
      ref={ref}
      labelId={labelId}
      legend={legend && series.length > 1 ? series.map((s, si) => ({ label: s.label, tone: toneOf(si), mark: "dot" as const })) : undefined}
      table={{
        columns: ["Series", xLabel, yLabel, ...(zMax > 0 ? [zLabel] : [])],
        rows: all.map((p) => [p.label ?? series[p.si].label, formatX(p.x), formatY(p.y), ...(zMax > 0 ? [formatZ(p.z ?? 0)] : [])]),
      }}
    >
      <ChartTray ref={plotRef} style={{ height }} role="img" aria-labelledby={card.label ? labelId : undefined}>
        {width > 0 && (
          <svg width={width} height={height} className="absolute inset-0 block overflow-visible">
            <YGrid ticks={yd.ticks} y={yAt} x0={padL} x1={width - PAD.r} format={formatY} grid={grid} />
            {grid &&
              xTicks.map((t) => (
                <line key={t} x1={Math.round(xAt(t)) + 0.5} x2={Math.round(xAt(t)) + 0.5} y1={PAD.t} y2={height - PAD.b} stroke="rgba(255,255,255,0.03)" />
              ))}
            <XLabels labels={xTicks.map(formatX)} x={(i) => xAt(xTicks[i])} y={height - 10} width={iw} minGap={40} />

            {active && activeKey != null && (
              <g aria-hidden>
                <line
                  x1={xAt(coords[activeKey * 2])}
                  x2={xAt(coords[activeKey * 2])}
                  y1={yAt(coords[activeKey * 2 + 1])}
                  y2={height - PAD.b}
                  stroke="rgba(255,255,255,0.16)"
                  strokeDasharray="2 3"
                />
                <line
                  x1={padL}
                  x2={xAt(coords[activeKey * 2])}
                  y1={yAt(coords[activeKey * 2 + 1])}
                  y2={yAt(coords[activeKey * 2 + 1])}
                  stroke="rgba(255,255,255,0.16)"
                  strokeDasharray="2 3"
                />
              </g>
            )}

            {/* Later series underneath. Each pearl grows in, left to right. */}
            {[...all.keys()].reverse().map((k) => {
              const p = all[k];
              const ti = toneOf(p.si);
              const t = tone(ti);
              const xf = (p.x - xd.min) / (xd.max - xd.min || 1);
              const g = clamp(grow * 1.6 - xf * 0.6, 0, 1);
              const r = radius(p.z, p.si) * g + (activeKey === k ? 1.5 : 0);
              if (r <= 0.2) return null;
              const x = xAt(coords[k * 2]);
              const y = yAt(coords[k * 2 + 1]);
              const dim = activeKey != null && activeKey !== k;
              return (
                <g key={k} style={{ opacity: dim ? 0.5 : 1 }} className="transition-opacity duration-150">
                  <circle cx={x} cy={y} r={r + 2} fill="#0c0c0d" />
                  {ti % 2 === 1 ? (
                    <circle cx={x} cy={y} r={Math.max(0.5, r - 0.75)} fill="#0c0c0d" stroke={t.stroke} strokeWidth="1.5" />
                  ) : (
                    <circle cx={x} cy={y} r={r} fill={ti === 0 ? "#ececec" : t.fill} />
                  )}
                </g>
              );
            })}

            <rect
              x={padL}
              y={0}
              width={iw}
              height={height}
              fill="transparent"
              onPointerMove={onPointer}
              onPointerDown={onPointer}
              onPointerLeave={() => setActiveKey(null)}
            />
          </svg>
        )}
        {tooltip && width > 0 && (
          <ChartTooltip
            open={active != null}
            x={active ? xAt(active.x) : 0}
            y={active ? yAt(active.y) - radius(active.z, active.si) - 2 : 0}
            bound={width}
            title={active ? active.label ?? series[active.si].label : ""}
            rows={
              active
                ? [
                    { label: xLabel, value: formatX(active.x), tone: toneOf(active.si), mark: "dot" as const },
                    { label: yLabel, value: formatY(active.y), tone: toneOf(active.si), mark: "dot" as const },
                    ...(zMax > 0 && active.z != null ? [{ label: zLabel, value: formatZ(active.z), tone: toneOf(active.si), mark: "dot" as const }] : []),
                  ]
                : []
            }
          />
        )}
      </ChartTray>
    </ChartCard>
  );
});

export default ScatterChart;

"use client";

import { forwardRef, useId, useState, type PointerEvent, type ReactNode } from "react";
import { ChartCard, ChartTray, type ChartCardProps } from "./ChartCard";
import { useTween, useWidth } from "./hooks";
import { SLICE_FILLS, arcPath, clamp } from "./scale";

// Progress toward several goals as concentric rings. Each ring is a recessed track cut into the
// tray; the progress is a popout arc in it, outermost first and stepping down in luminance
// inward. The rings run 270° clockwise from twelve o'clock and their names sit in the open
// quarter. Hovering a ring dims the others and puts its number in the middle.

export interface RadialBarDatum {
  label: string;
  value: number;
  /** Default 100. */
  max?: number;
}

export interface RadialBarChartProps extends Omit<ChartCardProps, "legend" | "table" | "children"> {
  data: RadialBarDatum[];
  /** Diameter in px. Default 208. */
  diameter?: number;
  /** Ring thickness in px. Default 10. */
  thickness?: number;
  /** Space between rings in px. Default 6. */
  gap?: number;
  /** Shown in the middle when nothing is active. */
  centerValue?: ReactNode;
  centerLabel?: ReactNode;
  /** Formats a ring's value. Default: percent of its max. */
  formatValue?: (value: number, max: number) => string;
  animateOnMount?: boolean;
}

const SWEEP = 270;
const defaultFormat = (v: number, max: number) => `${Math.round((v / (max || 1)) * 100)}%`;

export const RadialBarChart = forwardRef<HTMLDivElement, RadialBarChartProps>(function RadialBarChart(
  {
    data,
    diameter = 208,
    thickness = 10,
    gap = 6,
    centerValue,
    centerLabel,
    formatValue = defaultFormat,
    animateOnMount = true,
    ...card
  },
  ref
) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const labelId = `${uid}-label`;
  const [trayRef, width] = useWidth<HTMLDivElement>();
  const [active, setActive] = useState<number | null>(null);
  const fracs = data.map((d) => clamp(d.value / (d.max ?? 100), 0, 1));
  const shown = useTween(fracs, animateOnMount, 1);

  const D = Math.max(120, Math.min(diameter, width ? width - 24 : diameter));
  const c = D / 2;
  const rOuter = c - thickness / 2 - 2;
  const radius = (k: number) => rOuter - k * (thickness + gap);
  const rings = data.filter((_, k) => radius(k) - thickness / 2 > 8);

  const onPointer = (e: PointerEvent<SVGSVGElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const d = Math.hypot(e.clientX - rect.left - c, e.clientY - rect.top - c);
    const k = Math.round((rOuter - d) / (thickness + gap));
    setActive(k >= 0 && k < rings.length && Math.abs(radius(k) - d) <= thickness / 2 + gap / 2 ? k : null);
  };

  const face =
    active == null
      ? { value: centerValue, label: centerLabel }
      : { value: formatValue(data[active].value, data[active].max ?? 100), label: data[active].label };

  return (
    <ChartCard
      {...card}
      ref={ref}
      labelId={labelId}
      table={{
        columns: ["Goal", "Value", "Target"],
        rows: data.map((d) => [d.label, formatValue(d.value, d.max ?? 100), String(d.max ?? 100)]),
      }}
    >
      <ChartTray ref={trayRef} className="flex justify-center p-4">
        <div className="relative" style={{ width: D, height: D }}>
          <svg
            width={D}
            height={D}
            className="block overflow-visible"
            role="img"
            aria-labelledby={card.label ? labelId : undefined}
            onPointerMove={onPointer}
            onPointerLeave={() => setActive(null)}
          >
            <defs>
              <linearGradient id={`${uid}-pop`} gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2={D}>
                <stop offset="0%" stopColor="#f5f5f5" />
                <stop offset="100%" stopColor="#d9d9d9" />
              </linearGradient>
            </defs>
            {rings.map((d, k) => {
              const r = radius(k);
              const f = shown[k];
              const dim = active != null && active !== k;
              return (
                <g key={k} className="transition-opacity duration-150" style={{ opacity: dim ? 0.4 : 1 }}>
                  <path d={arcPath(c, c, r, 0, SWEEP)} fill="none" stroke="#070707" strokeWidth={thickness} strokeLinecap="round" />
                  {f > 0.002 && (
                    <path
                      d={arcPath(c, c, r, 0, Math.max(0.5, SWEEP * f))}
                      fill="none"
                      stroke={k === 0 ? `url(#${uid}-pop)` : SLICE_FILLS[Math.min(k, SLICE_FILLS.length - 1)]}
                      strokeWidth={thickness - 2}
                      strokeLinecap="round"
                    />
                  )}
                  <text
                    x={c - 10}
                    y={c - r}
                    textAnchor="end"
                    dominantBaseline="middle"
                    style={{ fontSize: 10.5, fontFeatureSettings: "'tnum'" }}
                  >
                    <tspan fill={active === k ? "rgb(245 245 245)" : "rgb(163 163 163)"}>{d.label}</tspan>
                    <tspan fill="rgb(115 115 115)" dx="5">
                      {formatValue(d.value, d.max ?? 100)}
                    </tspan>
                  </text>
                </g>
              );
            })}
          </svg>
          {(face.value != null || face.label != null) && (
            <div aria-hidden className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center text-center">
              {face.value != null && (
                <span className="text-[20px] font-semibold leading-none tracking-[-0.04em] text-neutral-100 tabular-nums">{face.value}</span>
              )}
              {face.label != null && <span className="mt-1.5 max-w-[40%] truncate text-[11px] text-neutral-500">{face.label}</span>}
            </div>
          )}
        </div>
      </ChartTray>
    </ChartCard>
  );
});

export default RadialBarChart;

"use client";

import { forwardRef, useId, type HTMLAttributes } from "react";
import { cn } from "@/lib/utils";
import { useTween, useWidth } from "./hooks";
import { areaPath, barPath, linear, smoothPath, tone } from "./scale";

// A word-sized chart for stat tiles and table cells: no card, no axes. The line variant ends in a
// pearl on the latest value; the bar variant lights only the latest bar as popout, so "now" is
// the brightest thing in it.

export interface SparklineProps extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  data: number[];
  variant?: "line" | "area" | "bar";
  /** Height in px. Default 36. */
  height?: number;
  /** Luminance step for the line. Default 0. */
  tone?: number;
  /** Accessible summary, e.g. "Signups, last 14 days, rising". */
  label?: string;
  animateOnMount?: boolean;
}

export const Sparkline = forwardRef<HTMLDivElement, SparklineProps>(function Sparkline(
  { data, variant = "line", height = 36, tone: toneIndex = 0, label, animateOnMount = true, className, style, ...rest },
  ref
) {
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const [boxRef, width] = useWidth<HTMLDivElement>();
  const shown = useTween(data, animateOnMount);
  const n = data.length;
  const lo = Math.min(...data, variant === "bar" ? 0 : Infinity);
  const hi = Math.max(...data);
  const t = tone(toneIndex);

  const setRefs = (node: HTMLDivElement | null) => {
    boxRef(node);
    if (typeof ref === "function") ref(node);
    else if (ref) ref.current = node;
  };

  let body = null;
  if (width > 0 && n > 0) {
    if (variant === "bar") {
      const gap = 2;
      const bw = Math.max(1, (width - gap * (n - 1)) / n);
      const yAt = linear(0, hi || 1, height, 2);
      body = shown.map((v, i) => {
        const y = yAt(Math.max(0, v));
        const last = i === n - 1;
        return (
          <path
            key={i}
            d={barPath(i * (bw + gap), y, bw, Math.max(1.5, height - y), 2, "top")}
            fill={last ? `url(#${uid}-pop)` : "rgba(255,255,255,0.2)"}
          />
        );
      });
    } else {
      const pad = 5;
      const xAt = (i: number) => pad + (n <= 1 ? 0 : (i / (n - 1)) * (width - pad * 2));
      const yAt = linear(lo, hi === lo ? lo + 1 : hi, height - pad, pad);
      const pts = shown.map((v, i) => [xAt(i), yAt(v)] as const);
      const [ex, ey] = pts[n - 1];
      body = (
        <>
          {variant === "area" && <path d={areaPath(pts, height, true)} fill={`url(#${uid}-a)`} />}
          <path d={smoothPath(pts)} fill="none" stroke={t.stroke} strokeWidth="1.75" strokeDasharray={t.dash} strokeLinecap="round" strokeLinejoin="round" />
          <circle cx={ex} cy={ey} r="5" fill="#151516" />
          <circle cx={ex} cy={ey} r="2.75" fill={toneIndex === 0 ? "#f0f0f0" : t.stroke} />
        </>
      );
    }
  }

  return (
    <div
      {...rest}
      ref={setRefs}
      role="img"
      aria-label={label}
      className={cn("relative w-full", className)}
      style={{ height, ...style }}
    >
      {width > 0 && (
        <svg width={width} height={height} className="absolute inset-0 block overflow-visible" aria-hidden>
          <defs>
            <linearGradient id={`${uid}-a`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#fff" stopOpacity={t.area} />
              <stop offset="100%" stopColor="#fff" stopOpacity="0" />
            </linearGradient>
            <linearGradient id={`${uid}-pop`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#f5f5f5" />
              <stop offset="100%" stopColor="#d9d9d9" />
            </linearGradient>
          </defs>
          {body}
        </svg>
      )}
    </div>
  );
});

export default Sparkline;

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
